INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20F17G3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is a quadratic function with zeros at $x = -5$ and $x = 13$, and the coefficient of $x^2$ is $1$. What is the value of $g(1)$?', NULL, $lyceon_json$[{"key":"A","text":"$-72$"},{"key":"B","text":"$72$"},{"key":"C","text":"$-56$"},{"key":"D","text":"$-65$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $g$ has zeros at $x = -5$ and $x = 13$ with leading coefficient $1$, the function is $g(x) = (x + 5)(x - 13)$. Evaluating at $x = 1$: $g(1) = (1 + 5)(1 - 13) = (6)(-12) = -72$. The value $72$ results from dropping the negative sign, computing $|6 \\cdot (-12)| = 72$. The value $-56$ results from setting up the factors incorrectly as $(x - 5)(x + 13)$, giving $(1 - 5)(1 + 13) = (-4)(14) = -56$. The value $-65$ comes from reading the constant term of the expanded form $g(x) = x^2 - 8x - 65$ without substituting $x = 1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JIAW5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $14m^3 - 21m^2$?', NULL, $lyceon_json$[{"key":"A","text":"$7m(2m^2 - 3m)$"},{"key":"B","text":"$7m^2(2m + 3)$"},{"key":"C","text":"$7m^2(2m - 3)$"},{"key":"D","text":"$7m^3(2 - 3m)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The greatest common factor of $14m^3$ and $21m^2$ is $7m^2$. Factoring: $14m^3 \\div 7m^2 = 2m$ and $21m^2 \\div 7m^2 = 3$, giving $7m^2(2m - 3)$. The distractor $7m(2m^2 - 3m)$ only factors out $7m$ instead of the full GCF $7m^2$. The distractor $7m^2(2m + 3)$ uses addition instead of subtraction. The distractor $7m^3(2 - 3m)$ over-factors by extracting $m^3$ from a term that only has $m^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GJ0NP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -(x - 4)^2 + 9$. What is the maximum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'D', NULL, E'The function $g(x) = -(x - 4)^2 + 9$ is in vertex form $a(x - h)^2 + k$ with $a = -1$, $h = 4$, and $k = 9$. Since $a < 0$, the parabola opens downward and the vertex $(4, 9)$ is the maximum point. The maximum value of $g(x)$ is $9$. The value $-9$ results from negating the $k$ value. The value $-4$ comes from negating $h$, confusing the vertex coordinates. The value $4$ results from reading $h$ as the maximum output rather than the $x$-coordinate of the vertex.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2340T9D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills 37 bottles every 4 minutes. At this rate, how many bottles does the machine fill in 20 minutes?', NULL, $lyceon_json$[{"key":"A","text":"148"},{"key":"B","text":"185"},{"key":"C","text":"160"},{"key":"D","text":"740"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is 37 bottles per 4 minutes. In 20 minutes, the machine fills $\\frac{37}{4} \\times 20 = 185$ bottles. The answer 148 results from multiplying 37 by 4 instead of dividing. The answer 160 comes from incorrectly using 8 bottles per minute. The answer 740 comes from multiplying 37 by 20 without accounting for the 4-minute interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23YBWX0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following inequalities represents all values of $x$ that satisfy $7x - 13 > 22$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 5$"},{"key":"B","text":"$x < 5$"},{"key":"C","text":"$x > 3$"},{"key":"D","text":"$x > 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $13$ to both sides gives $7x > 35$, and dividing both sides by $7$ gives $x > 5$. The value $x < 5$ reverses the inequality direction, which is incorrect. The value $x > 3$ results from dividing $22$ by $7$ instead of $35$ by $7$. The value $x > 7$ results from incorrectly computing $\\frac{35}{5}$ rather than $\\frac{35}{7}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24IITX3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive difference between the two solutions of $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factor the quadratic: $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$. The solutions are $x = 4$ and $x = 7$. The positive difference is $7 - 4 = 3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM257L4AZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 residents in a city found that 58% support a proposed park expansion. The margin of error for this estimate is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 58% of all city residents support the park expansion."},{"key":"B","text":"Between 54% and 62% of the sampled residents support the park expansion."},{"key":"C","text":"It is plausible that between 54% and 62% of all city residents support the park expansion."},{"key":"D","text":"If another sample of 400 residents is taken, exactly 58% will support the park expansion."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is $58\\% \\pm 4\\%$, or between 54% and 62%. The statement that exactly 58% of all residents support it ignores sampling variability. The claim that between 54% and 62% of the sampled residents support it misapplies the interval to the sample rather than the population. The claim about another sample producing exactly 58% confuses the point estimate with a guaranteed outcome of future samples.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25FEF1A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A school district wants to determine whether a new reading program improves student comprehension scores. They select 150 students: 75 students at School A use the new program, and 75 students at School B use the traditional program. After 12 weeks, the students using the new program have higher average comprehension scores. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new reading program causes higher comprehension scores for all students in the district."},{"key":"B","text":"The difference in scores may be due to the new program or to pre-existing differences between the two schools."},{"key":"C","text":"The new reading program is more effective than the traditional program for every individual student."},{"key":"D","text":"School A has better teachers than School B, which explains the higher scores."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students were not randomly assigned to the programs but instead separated by school, this is an observational study with a confounding variable: the schools themselves may differ in ways that affect comprehension scores. The appropriate conclusion is that the observed difference may be due to the program or to pre-existing differences between the schools. Claiming the program causes higher scores ignores the lack of random assignment. Claiming it is more effective for every student overgeneralizes from group averages to individuals. Attributing the difference to teacher quality introduces an unsupported claim not established by the study.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM267D5ZA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles form a linear pair. If one angle measures $131°$, what is the measure of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$59°$"},{"key":"C","text":"$131°$"},{"key":"D","text":"$229°$"}]$lyceon_json$::jsonb, 'A', NULL, E'Angles in a linear pair are supplementary, meaning they sum to $180°$. Therefore, the other angle is $180° - 131° = 49°$. The distractor $59°$ results from an arithmetic error in the subtraction. The distractor $131°$ confuses supplementary angles with vertical angles, which would be equal. The distractor $229°$ incorrectly subtracts from $360°$ instead of $180°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26S31ZC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^x + 5$. Which of the following best describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $5$"},{"key":"B","text":"All real numbers greater than $0$"},{"key":"C","text":"All real numbers greater than $3$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'For $f(x) = 3 \\cdot 2^x + 5$, the term $3 \\cdot 2^x$ is always positive and approaches $0$ as $x$ approaches negative infinity. Therefore $f(x)$ approaches $5$ from above but never equals $5$, and $f(x)$ increases without bound as $x$ increases. The range is all real numbers greater than $5$. Stating the range is all real numbers greater than $0$ ignores the vertical shift of $5$, treating the asymptote as $y = 0$. Stating the range is all real numbers greater than $3$ confuses the coefficient $3$ with the horizontal asymptote. Stating the range is all real numbers incorrectly treats $f$ as if it could take any output value, overlooking the horizontal asymptote.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM277ZWJE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A set of 7 data values has a mean of 23. When an eighth value of 39 is added to the set, what is the new mean of the 8 values?', NULL, $lyceon_json$[{"key":"A","text":"25"},{"key":"B","text":"31"},{"key":"C","text":"26"},{"key":"D","text":"24"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the original 7 values is $7 \\times 23 = 161$. Adding 39 gives a new sum of $161 + 39 = 200$. The new mean is $\\frac{200}{8} = 25$. The value 31 comes from averaging only 23 and 39, ignoring the other data points. The value 26 results from a computational error such as dividing by 7 instead of 8 or miscalculating the original sum. The value 24 comes from taking the midpoint idea or partial reasoning that the mean shifts only halfway toward the new value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28CMKCR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A rectangular box has a volume of 1,170 cubic centimeters. The box has a length of 13 cm and a width of 9 cm. What is the height of the box, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"9"},{"key":"B","text":"10"},{"key":"C","text":"90"},{"key":"D","text":"117"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a rectangular box is $V = l \\times w \\times h$. Substituting: $1{,}170 = 13 \\times 9 \\times h$, so $1{,}170 = 117h$, which gives $h = 10$ cm. The distractor 9 results from confusing the width with the height. The distractor 90 comes from dividing the volume by only one dimension: $\\frac{1{,}170}{13} = 90$. The distractor 117 results from computing $13 \\times 9 = 117$ and reporting the base area instead of solving for the height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M2DIO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{5(2x - 3)}{4} = \\frac{x + 11}{2}$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{8}$"},{"key":"B","text":"$\\frac{37}{10}$"},{"key":"C","text":"$\\frac{37}{8}$"},{"key":"D","text":"$\\frac{37}{6}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by 4 gives $5(2x - 3) = 2(x + 11)$. Expanding: $10x - 15 = 2x + 22$. Subtracting $2x$ from both sides: $8x - 15 = 22$. Adding 15 to both sides: $8x = 37$, so $x = \\frac{37}{8}$. The value $\\frac{7}{8}$ results from a sign error when moving $-15$ to the right side, computing $22 - 15 = 7$ instead of $22 + 15 = 37$. The value $\\frac{37}{10}$ results from failing to subtract $2x$ from both sides, leaving $10x = 37$. The value $\\frac{37}{6}$ results from an arithmetic slip in combining the $x$ terms as $6x$ instead of $8x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AESZ2C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has a circumference of $46\\pi$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The circumference of a circle is $C = 2\\pi r$. Setting $2\\pi r = 46\\pi$ and dividing both sides by $2\\pi$ gives $r = 23$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BEYDF1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{18x^5 y^3}{6x^2 y^7}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^3 y^4$"},{"key":"B","text":"$\\frac{3x^7}{y^{10}}$"},{"key":"C","text":"$\\frac{3x^3}{y^4}$"},{"key":"D","text":"$\\frac{12x^3}{y^4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Simplify the coefficient: $18 \\div 6 = 3$. For $x$: $x^{5-2} = x^3$. For $y$: $y^{3-7} = y^{-4} = \\frac{1}{y^4}$. The result is $\\frac{3x^3}{y^4}$. The distractor $3x^3 y^4$ incorrectly makes the $y$ exponent positive. The distractor $\\frac{3x^7}{y^{10}}$ adds the exponents instead of subtracting them. The distractor $\\frac{12x^3}{y^4}$ subtracts the coefficients ($18 - 6 = 12$) instead of dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BN5F42', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + 3x = 28$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Rearrange to standard form: $x^2 + 3x - 28 = 0$. Factor: $(x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. Since $x > 0$, the answer is $x = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CBO3RR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has a radius of 14. A central angle of $\\frac{5\\pi}{7}$ radians intercepts a sector of the circle. What is the area of this sector?', NULL, $lyceon_json$[{"key":"A","text":"$10\\pi$"},{"key":"B","text":"$70\\pi$"},{"key":"C","text":"$140\\pi$"},{"key":"D","text":"$196\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $A = \\frac{1}{2}r^2\\theta$. Substituting: $A = \\frac{1}{2}(14)^2 \\cdot \\frac{5\\pi}{7} = \\frac{1}{2}(196) \\cdot \\frac{5\\pi}{7} = 98 \\cdot \\frac{5\\pi}{7} = \\frac{490\\pi}{7} = 70\\pi$. The distractor $10\\pi$ equals the arc length $r\\theta = 14 \\cdot \\frac{5\\pi}{7} = 10\\pi$, confusing arc length with sector area. The distractor $140\\pi$ omits the $\\frac{1}{2}$ factor, computing $r^2\\theta = 196 \\cdot \\frac{5\\pi}{7} = 140\\pi$. The distractor $196\\pi$ is the area of the full circle $\\pi r^2$, ignoring the central angle entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E2HNOZ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'If $-3x + 19 \\geq 4$, what is the greatest integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Subtracting $19$ from both sides gives $-3x \\geq -15$. Dividing both sides by $-3$ and reversing the inequality yields $x \\leq 5$. The greatest integer satisfying $x \\leq 5$ is $5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8N7SI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A right triangle has legs of length 9 and 40. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"31"},{"key":"B","text":"41"},{"key":"C","text":"49"},{"key":"D","text":"1,681"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean Theorem: $c^2 = 9^2 + 40^2 = 81 + 1{,}600 = 1{,}681$. Taking the square root gives $c = 41$. The distractor 31 comes from subtracting the legs ($40 - 9$) instead of applying the theorem. The distractor 49 adds the legs ($40 + 9$), which is not how the Pythagorean Theorem works. The distractor 1,681 is the value of $c^2$ before taking the square root, representing an incomplete calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJ0WIJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $9x + 14 = 77$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$63$"},{"key":"D","text":"$\\frac{91}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract 14 from both sides: $9x = 63$. Divide by 9: $x = 7$. The value $-7$ applies a sign error when dividing. The value $63$ results from subtracting 14 correctly but forgetting to divide by 9. The value $\\frac{91}{9}$ results from adding 14 to 77 instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FWUIPO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular patio has a length of 17 feet and a width of 9 feet. What is the area of the patio, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"52"},{"key":"B","text":"136"},{"key":"C","text":"153"},{"key":"D","text":"26"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $17 \\times 9 = 153$ square feet. The distractor 52 equals the perimeter $2(17 + 9)$, which confuses perimeter with area. The distractor 136 results from an arithmetic error such as computing $17 \\times 8$. The distractor 26 equals half the perimeter $(17 + 9)$, which is neither the area nor the full perimeter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G8X2ST', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(2) = 63$ and $f(4) = 567$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'From $f(2) = a \\cdot b^2 = 63$ and $f(4) = a \\cdot b^4 = 567$, dividing the second equation by the first gives $\\frac{a \\cdot b^4}{a \\cdot b^2} = \\frac{567}{63}$, so $b^2 = 9$ and $b = 3$ (since $b > 0$). Substituting back, $a \\cdot 9 = 63$, so $a = 7$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H9RE2H', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = x^2 - 14x + 53$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Completing the square: $f(x) = x^2 - 14x + 53 = (x - 7)^2 - 49 + 53 = (x - 7)^2 + 4$. Since $(x - 7)^2 \\geq 0$ for all real $x$, the minimum value of $f(x)$ is $0 + 4 = 4$, attained when $x = 7$. Alternatively, the vertex occurs at $x = -\\frac{-14}{2(1)} = 7$, and $f(7) = 49 - 98 + 53 = 4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HA882Z', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line represented by the equation $5x + 3y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{5}{3}$"},{"key":"B","text":"$\\frac{5}{3}$"},{"key":"C","text":"$\\frac{3}{5}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rearranging to slope-intercept form: $3y = -5x + 21$, so $y = -\\frac{5}{3}x + 7$. The slope is $-\\frac{5}{3}$. The value $\\frac{5}{3}$ drops the negative sign when moving the $5x$ term. The value $\\frac{3}{5}$ inverts the fraction, confusing the coefficient of $x$ with the coefficient of $y$. The value 7 is the $y$-intercept, not the slope, reflecting confusion about which part of slope-intercept form gives the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HCM6GI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $p$ in the equation $3p + 17 = 41$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Subtracting 17 from both sides gives $3p = 24$. Dividing both sides by 3 gives $p = 8$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HY68P3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does $4x^2 - 20x + 25 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Use the discriminant $b^2 - 4ac$ with $a = 4$, $b = -20$, $c = 25$: $(-20)^2 - 4(4)(25) = 400 - 400 = 0$. A discriminant of $0$ means exactly $1$ distinct real solution (a repeated root). Indeed, $4x^2 - 20x + 25 = (2x - 5)^2$, so $x = \\frac{5}{2}$ is the only solution. The distractor $0$ incorrectly concludes a zero discriminant means no solutions (confusing it with a negative discriminant). The distractor $2$ assumes every quadratic with real coefficients has two distinct solutions. The distractor $4$ confuses the leading coefficient with the number of solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I1Q61S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $143°$. If angle $P$ measures $61°$, what is the measure of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$82°$"},{"key":"C","text":"$98°$"},{"key":"D","text":"$119°$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $143° = 61° + Q$, giving $Q = 82°$. The distractor $37°$ equals the interior angle at $R$ (since $180° - 143° = 37°$) — this finds the wrong angle. The distractor $98°$ results from subtracting the correct answer from $180°$ rather than recognizing the exterior angle relationship. The distractor $119°$ comes from computing $180° - 61° = 119°$, ignoring the exterior angle information entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I4RL36', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'If $5x + 2y = 34$ and $3x - 2y = -2$, what is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Adding the two equations eliminates $y$: $(5x + 2y) + (3x - 2y) = 34 + (-2)$, giving $8x = 32$ and $x = 4$. Substituting back into $3(4) - 2y = -2$ gives $12 - 2y = -2$, so $-2y = -14$ and $y = 7$. Therefore $x + y = 4 + 7 = 11$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J4DPTY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells paperbacks for $\\$7$ each and hardcovers for $\\$13$ each. A student buys $11$ books and pays a total of $\\$101$. How many hardcovers did the student buy?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the number of hardcovers and $p$ the number of paperbacks. The system is $p + h = 11$ and $7p + 13h = 101$. Substituting $p = 11 - h$ into the cost equation gives $7(11 - h) + 13h = 101$, which simplifies to $77 - 7h + 13h = 101$, then $6h = 24$, so $h = 4$. The value $3$ results from an arithmetic slip when simplifying. The value $5$ comes from setting up the cost equation incorrectly (e.g., swapping the prices). The value $7$ is the number of paperbacks, not hardcovers.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JP471Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The population of a town was 12,400 at the start of 2021. The population increased by 7% from 2021 to 2022 and then decreased by 5% from 2022 to 2023. What was the overall percent change in the town''s population from the start of 2021 to the start of 2023, to the nearest tenth of a percent?', NULL, $lyceon_json$[{"key":"A","text":"$1.65\\%$ increase"},{"key":"B","text":"$2.0\\%$ increase"},{"key":"C","text":"$2.35\\%$ increase"},{"key":"D","text":"$12.0\\%$ increase"}]$lyceon_json$::jsonb, 'A', NULL, E'The population after 2021 is $12{,}400 \\times 1.07 = 13{,}268$. After the 5% decrease: $13{,}268 \\times 0.95 = 12{,}604.60$. The overall change is $12{,}604.60 - 12{,}400 = 204.60$, so the percent change is $\\frac{204.60}{12{,}400} \\times 100 \\approx 1.65\\%$. The 2.0% answer comes from simply subtracting the percentages ($7\\% - 5\\% = 2\\%$), which ignores that the 5% decrease applies to the larger post-increase population. The 2.35% answer results from a rounding or arithmetic error during the multiplication steps. The 12.0% answer comes from adding the two percentages ($7\\% + 5\\%$) instead of applying them sequentially.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L7VET6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cartographer uses a scale where 3 centimeters on the map represents 14 kilometers of actual distance. Two cities are 47 kilometers apart. What is the distance, in centimeters, between the two cities on the map, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"10.1"},{"key":"B","text":"9.4"},{"key":"C","text":"219.3"},{"key":"D","text":"6.1"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the proportion $\\frac{3}{14} = \\frac{x}{47}$, we get $x = \\frac{3 \\times 47}{14} = \\frac{141}{14} \\approx 10.071$, which rounds to 10.1 centimeters. The value 9.4 results from a rounding or arithmetic error in the division. The value 219.3 comes from multiplying $\\frac{14}{3} \\times 47$, which gives kilometers per centimeter times the distance, a unit inversion. The value 6.1 comes from setting up the proportion incorrectly as $\\frac{3}{47} \\times 14 \\times \\frac{47}{14}$ with errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MK6ELP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{x^2 + 3x - 28}{x^2 - 16}$ for $x \\neq \\pm 4$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 7}{x - 4}$"},{"key":"B","text":"$\\frac{x + 7}{x - 4}$"},{"key":"C","text":"$\\frac{x + 7}{x + 4}$"},{"key":"D","text":"$\\frac{x - 4}{x + 7}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factor the numerator: $x^2 + 3x - 28 = (x + 7)(x - 4)$. Factor the denominator: $x^2 - 16 = (x + 4)(x - 4)$. Cancel the common factor $(x - 4)$ to get $\\frac{x + 7}{x + 4}$. The distractor $\\frac{x - 7}{x - 4}$ uses incorrect signs in the numerator factoring. The distractor $\\frac{x + 7}{x - 4}$ cancels the wrong factor, removing $(x + 4)$ from the denominator instead of $(x - 4)$. The distractor $\\frac{x - 4}{x + 7}$ inverts the fraction after cancellation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NR4XDO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'For what value of $a$ does the inequality $ax + 7 > 3x + 19$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$a = -3$"},{"key":"B","text":"$a = 0$"},{"key":"C","text":"$a = 3$"},{"key":"D","text":"$a = 7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting the inequality gives $(a - 3)x > 12$. When $a = 3$, the left side becomes $0 \\cdot x = 0$, and the inequality $0 > 12$ is false for every real $x$, so there is no solution. When $a \\neq 3$, the coefficient of $x$ is nonzero and the inequality can be solved for $x$, producing a nonempty solution set. The value $a = -3$ confuses the sign of the coefficient. The value $a = 0$ conflates setting the entire left side to zero with setting the coefficient to zero. The value $a = 7$ incorrectly sets $a$ equal to $7$ from the right-hand constant $19$ minus $12$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NUFYNS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x + 5}$ for $x \\neq -\\frac{5}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x - 5$"},{"key":"D","text":"$2x^2 - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognize that $4x^2 - 25 = (2x)^2 - 5^2 = (2x - 5)(2x + 5)$. Dividing by $(2x + 5)$ cancels the common factor, leaving $2x - 5$. The distractor $2x + 5$ uses the wrong factor from the difference of squares. The distractor $4x - 5$ incorrectly simplifies $4x^2 \\div 2x = 4x$ without proper factoring. The distractor $2x^2 - 5$ incorrectly divides each term separately as $4x^2 \\div 2 = 2x^2$ and $25 \\div 5 = 5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NXZ2XR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ has the equation $5x + 13y = 52$, and line $n$ is perpendicular to line $m$ and passes through the point $(-2, 7)$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{13}$"},{"key":"B","text":"$\\frac{9}{5}$"},{"key":"C","text":"$\\frac{61}{13}$"},{"key":"D","text":"$\\frac{61}{5}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting line $m$ in slope-intercept form: $13y = -5x + 52$, so the slope of $m$ is $-\\frac{5}{13}$. The perpendicular slope is $\\frac{13}{5}$. Using point-slope form with $(-2, 7)$: $y - 7 = \\frac{13}{5}(x + 2)$, giving $y = \\frac{13}{5}x + \\frac{26}{5} + 7 = \\frac{13}{5}x + \\frac{26}{5} + \\frac{35}{5} = \\frac{13}{5}x + \\frac{61}{5}$. The $y$-intercept is $\\frac{61}{5}$. The value $\\frac{9}{5}$ results from a sign error, using $(x - 2)$ instead of $(x + 2)$, yielding $7 - \\frac{26}{5} = \\frac{9}{5}$. The value $\\frac{61}{13}$ results from using the original slope $-\\frac{5}{13}$ instead of the perpendicular slope. The value $\\frac{9}{13}$ combines both errors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O0QPUW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $p$ is defined by $p(x) = -2x^2 + 28x - 89$. What is the maximum value of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-89$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The vertex of $p(x) = -2x^2 + 28x - 89$ occurs at $x = -\\frac{28}{2(-2)} = 7$. Substituting, $p(7) = -2(49) + 28(7) - 89 = -98 + 196 - 89 = 9$. Since the leading coefficient is negative, the parabola opens downward and $9$ is the maximum value. The value $7$ is the $x$-coordinate of the vertex, not the maximum output of $p$. The value $-89$ is the constant term, which would only be the value at $x = 0$, not the maximum. The value $-9$ results from a sign error in the final computation, negating the correct result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OAKXBO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $ABC$, angle $C = 90°$. If $\\tan(A) = \\frac{15}{8}$, what is $\\sin(B)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{15}{17}$"},{"key":"B","text":"$\\frac{8}{15}$"},{"key":"C","text":"$\\frac{8}{17}$"},{"key":"D","text":"$\\frac{17}{15}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\tan(A) = \\frac{15}{8}$, the side opposite angle $A$ is 15 and the side adjacent to angle $A$ is 8. The hypotenuse is $\\sqrt{15^2 + 8^2} = \\sqrt{225 + 64} = \\sqrt{289} = 17$. Angle $B$ is complementary to angle $A$, so $\\sin(B) = \\cos(A) = \\frac{8}{17}$. The distractor $\\frac{15}{17}$ equals $\\sin(A)$, not $\\sin(B)$. The distractor $\\frac{8}{15}$ equals $\\tan(B)$, using the wrong trigonometric ratio. The distractor $\\frac{17}{15}$ is an inverted ratio that exceeds 1 and cannot be a valid sine value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2NM8U', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 5x^2 - 11$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$34$"},{"key":"C","text":"$45$"},{"key":"D","text":"$56$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$ into $f(x) = 5x^2 - 11$ gives $f(3) = 5(3)^2 - 11 = 5(9) - 11 = 45 - 11 = 34$. The value $4$ results from failing to square $x$, computing $5(3) - 11$ instead. The value $45$ comes from computing $5(9)$ but neglecting to subtract $11$. The value $56$ results from adding $11$ instead of subtracting it: $5(9) + 11 = 56$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P8HHK7', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The line $9x - 4y = 36$ intersects the $x$-axis at the point $(a, 0)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'At the $x$-axis, $y = 0$. Substituting into $9x - 4(0) = 36$ gives $9x = 36$, so $x = 4$. Therefore $a = 4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PA5CSB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line has a slope of $-\\frac{2}{5}$ and passes through the point $(10, -1)$. At what point does this line cross the $y$-axis?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 3)$"},{"key":"B","text":"$(0, -5)$"},{"key":"C","text":"$(0, 5)$"},{"key":"D","text":"$(0, -3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using point-slope form: $y - (-1) = -\\frac{2}{5}(x - 10)$, which gives $y + 1 = -\\frac{2}{5}x + 4$, so $y = -\\frac{2}{5}x + 3$. The $y$-intercept is $(0, 3)$. The point $(0, -5)$ results from substituting incorrectly into the equation and computing $-1 - 4 = -5$. The point $(0, 5)$ drops the negative from the slope, computing $\\frac{2}{5}(10) = 4$ and then $-1 + 4 + 2 = 5$. The point $(0, -3)$ applies a sign error on the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PJKEZC', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'Given the system $3x + 2y = 19$ and $x - 2y = -7$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 19 + (-7)$, giving $4x = 12$ and $x = 3$. The value $5$ is the $y$-value of the solution, not the $x$-value. The value $-3$ results from a sign error when adding the constant terms. The value $7$ comes from incorrectly computing $\\frac{12}{4}$ as $7$ or misreading the system.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PSV61K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'What is the value of $x$ that satisfies $\\frac{3}{x - 2} + \\frac{5}{x + 1} = \\frac{4x}{x^2 - x - 2}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/4', ARRAY['7/4', '1.75'], E'Note that $x^2 - x - 2 = (x - 2)(x + 1)$, so the common denominator is $(x - 2)(x + 1)$. Multiply both sides by $(x - 2)(x + 1)$: $3(x + 1) + 5(x - 2) = 4x$. Expand: $3x + 3 + 5x - 10 = 4x$. Simplify: $8x - 7 = 4x$, so $4x = 7$ and $x = \\frac{7}{4}$. Since $x = \\frac{7}{4}$ is neither $2$ nor $-1$, it is valid and does not create a zero denominator.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q18YB2', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $6x - 9y = 15$ and $4x - 6y = k$ have infinitely many solutions?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$15$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-10$"}]$lyceon_json$::jsonb, 'A', NULL, E'For infinitely many solutions, the two equations must be scalar multiples of each other. Dividing $6x - 9y = 15$ by $3$ gives $2x - 3y = 5$. Dividing $4x - 6y = k$ by $2$ gives $2x - 3y = \\frac{k}{2}$. These are the same equation when $\\frac{k}{2} = 5$, so $k = 10$. The value $15$ is the constant from the first equation without reducing to match the second. The value $5$ confuses $\\frac{k}{2} = 5$ with $k = 5$. The value $-10$ applies an incorrect sign when equating the constants.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QV6AV4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 + 3x - 40 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -8$ and $x = 5$"},{"key":"B","text":"$x = 8$ and $x = -5$"},{"key":"C","text":"$x = -10$ and $x = 4$"},{"key":"D","text":"$x = 10$ and $x = -4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: find two numbers that multiply to $-40$ and add to $3$. Those numbers are $8$ and $-5$: $x^2 + 3x - 40 = (x + 8)(x - 5) = 0$. Setting each factor to zero gives $x = -8$ and $x = 5$. The distractor $x = 8$ and $x = -5$ reverses the signs of both solutions. The distractor $x = -10$ and $x = 4$ uses an incorrect factor pair ($-10 \\times 4 = -40$ but $-10 + 4 = -6 \\neq 3$). The distractor $x = 10$ and $x = -4$ also uses an incorrect pair with reversed signs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QWLXU8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a volume of $147\\pi$ cubic inches and a height of 9 inches. What is the radius of the base of the cone, in inches?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Substituting the given values: $147\\pi = \\frac{1}{3}\\pi r^2 (9)$. Simplifying the right side: $147\\pi = 3\\pi r^2$. Dividing both sides by $3\\pi$: $r^2 = 49$. Taking the positive square root: $r = 7$ inches.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2REUU0F', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $h$ is defined such that $h(2) = 17$ and $h(9) = -18$. For what value of $x$ does $h(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{7}{5}$"},{"key":"B","text":"$\\frac{27}{7}$"},{"key":"C","text":"$\\frac{27}{5}$"},{"key":"D","text":"$\\frac{62}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $\\frac{-18 - 17}{9 - 2} = \\frac{-35}{7} = -5$. Using point-slope form: $h(x) = -5(x - 2) + 17 = -5x + 10 + 17 = -5x + 27$. Setting $h(x) = 0$: $-5x + 27 = 0$, so $x = \\frac{27}{5}$. The value $-\\frac{7}{5}$ results from a sign error, using a slope of $+5$ instead of $-5$, which gives $h(x) = 5x + 7$ and $x = -\\frac{7}{5}$. The value $\\frac{27}{7}$ results from an arithmetic slip, dividing 27 by the denominator of the slope fraction (7) instead of the absolute value of the slope (5). The value $\\frac{62}{5}$ results from swapping the function values of the two points, computing the $y$-intercept as 62 instead of 27.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RIN2P2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'When $6x^3 + 11x^2 - 19x + 6$ is divided by $2x - 1$, what is the resulting quotient?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 7x - 6$"},{"key":"B","text":"$3x^2 + 4x - 6$"},{"key":"C","text":"$3x^2 + 7x + 6$"},{"key":"D","text":"$3x^2 - 7x + 6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Perform polynomial long division. Divide $6x^3$ by $2x$ to get $3x^2$. Multiply $3x^2(2x - 1) = 6x^3 - 3x^2$. Subtract: $(6x^3 + 11x^2) - (6x^3 - 3x^2) = 14x^2$. Bring down $-19x$ to get $14x^2 - 19x$. Divide $14x^2$ by $2x$ to get $7x$. Multiply $7x(2x - 1) = 14x^2 - 7x$. Subtract: $(14x^2 - 19x) - (14x^2 - 7x) = -12x$. Bring down $+6$ to get $-12x + 6$. Divide $-12x$ by $2x$ to get $-6$. Multiply $-6(2x - 1) = -12x + 6$. Subtract to get $0$. The quotient is $3x^2 + 7x - 6$. The distractor $3x^2 + 4x - 6$ miscalculates the second subtraction step. The distractor $3x^2 + 7x + 6$ flips the sign of the constant term. The distractor $3x^2 - 7x + 6$ reverses the signs of the last two terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RRYEMD', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$17$ plus $\\$4$ per mile driven. If a customer can spend no more than $\\$53$ on a single delivery, which inequality represents the possible number of miles $m$ the delivery can cover?', NULL, $lyceon_json$[{"key":"A","text":"$m \\leq 9$"},{"key":"B","text":"$m \\geq 9$"},{"key":"C","text":"$m \\leq 36$"},{"key":"D","text":"$m \\leq 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $4m + 17$, and this must be at most $53$: $4m + 17 \\leq 53$. Subtracting $17$ from both sides gives $4m \\leq 36$, and dividing by $4$ gives $m \\leq 9$. The inequality $m \\geq 9$ incorrectly reverses the direction. The value $m \\leq 36$ stops after subtracting without dividing by $4$. The value $m \\leq 7$ results from incorrectly subtracting $25$ instead of $17$ from $53$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T8ZTYX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x - 7)(2x + 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + x - 35$"},{"key":"B","text":"$6x^2 - x - 35$"},{"key":"C","text":"$6x^2 + 29x - 35$"},{"key":"D","text":"$6x^2 - 29x - 35$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using FOIL: $(3x)(2x) = 6x^2$, $(3x)(5) = 15x$, $(-7)(2x) = -14x$, $(-7)(5) = -35$. Combining: $6x^2 + 15x - 14x - 35 = 6x^2 + x - 35$. The distractor $6x^2 - x - 35$ reverses the sign of the middle term. The distractor $6x^2 + 29x - 35$ adds $15x + 14x$ instead of $15x - 14x$, ignoring the negative sign on $7$. The distractor $6x^2 - 29x - 35$ both adds the magnitudes and applies an incorrect negative sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TFNU0A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What value of $c$ makes $9x^2 + 42x + c$ a perfect square trinomial?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49', ARRAY['49'], E'A perfect square trinomial has the form $(ax + b)^2 = a^2 x^2 + 2abx + b^2$. Here $a^2 = 9$, so $a = 3$. Then $2ab = 42$, giving $2(3)b = 42$, so $b = 7$. Therefore $c = b^2 = 49$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TM4OWZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 5x + 3$ and $y = 2x - 7$ has two solutions. What is the sum of the $x$-coordinates of these solutions?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the expressions equal: $x^2 - 5x + 3 = 2x - 7$. Rearranging: $x^2 - 7x + 10 = 0$. By Vieta''s formulas, the sum of the roots equals $-\\frac{b}{a} = -\\frac{-7}{1} = 7$. (Alternatively, factor as $(x - 2)(x - 5) = 0$, giving $x = 2$ and $x = 5$ with sum $7$.) The distractor $5$ uses only the coefficient $-5$ from the original quadratic. The distractor $10$ is the product of the roots rather than the sum. The distractor $-7$ takes the coefficient $-7$ without negating it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V4RLXI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher finds that the line of best fit for a data set relating years of experience, $x$, to annual salary in thousands of dollars, $y$, is $y = 4.7x + 29$. According to this model, what is the predicted annual salary, in thousands of dollars, for someone with 11 years of experience?', NULL, $lyceon_json$[{"key":"A","text":"$80.7$"},{"key":"B","text":"$51.7$"},{"key":"C","text":"$33.7$"},{"key":"D","text":"$76.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 11$ into the model: $y = 4.7(11) + 29 = 51.7 + 29 = 80.7$ thousand dollars. The value 51.7 results from computing only $4.7 \\times 11$ and omitting the constant term 29. The value 33.7 comes from adding 4.7 to 29 instead of multiplying 4.7 by 11, treating the slope as a one-time addition. The value 76.0 results from a multiplication error such as computing $4.7 \\times 10 = 47$ instead of $4.7 \\times 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VXZPEU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym charges a one-time enrollment fee of $\\$35$ and a monthly membership fee of $\\$19$. Which function $f$ gives the total cost, in dollars, after $m$ months of membership?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 19m + 35$"},{"key":"B","text":"$f(m) = 35m + 19$"},{"key":"C","text":"$f(m) = 54m$"},{"key":"D","text":"$f(m) = 19m - 35$"}]$lyceon_json$::jsonb, 'A', NULL, E'The monthly fee of $\\$19$ is the rate per month, giving the term $19m$. The one-time enrollment fee of $\\$35$ is the initial cost, giving $f(m) = 19m + 35$. The function $f(m) = 35m + 19$ reverses the roles of the monthly fee and the enrollment fee. The function $f(m) = 54m$ adds the two costs together as if both recur monthly, producing an equation that overstates the total each month. The function $f(m) = 19m - 35$ incorrectly subtracts the enrollment fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WY3WY6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A music teacher charges $\\$20$ per lesson plus a one-time enrollment fee of $\\$40$. If a student has paid a total of $\\$280$, how many lessons has the student taken?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$12$"},{"key":"C","text":"$14$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation is $20n + 40 = 280$. Subtracting 40 from both sides gives $20n = 240$. Dividing by 20 gives $n = 12$. The value 11 results from an arithmetic slip when subtracting 40 from 280 (getting 220 instead of 240). The value 14 results from ignoring the enrollment fee and dividing 280 directly by 20. The value 16 results from adding the enrollment fee instead of subtracting, computing $(280 + 40) \\div 20$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X9821N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a group of 200 people surveyed, 68 own a bicycle, 53 own a skateboard, and 19 own both a bicycle and a skateboard. If one person is selected at random from those who own a bicycle, what is the probability that this person also owns a skateboard?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{68}$"},{"key":"C","text":"$\\frac{19}{53}$"},{"key":"D","text":"$\\frac{49}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The conditional probability of owning a skateboard given that the person owns a bicycle is $P(\\text{skateboard} \\mid \\text{bicycle}) = \\frac{19}{68}$, since 19 of the 68 bicycle owners also own a skateboard. The fraction $\\frac{19}{200}$ uses the total group as the denominator instead of conditioning on bicycle owners. The fraction $\\frac{19}{53}$ conditions on skateboard owners rather than bicycle owners, answering the wrong conditional question. The value $\\frac{49}{200}$ comes from subtracting 19 from 68 and dividing by 200, a setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y1LHX1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store originally prices a jacket at $\\$130$. During a sale, the price is reduced by 15%. A customer uses an additional coupon for 8% off the sale price. What is the final price of the jacket, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$100.10$"},{"key":"B","text":"$\\$101.66$"},{"key":"C","text":"$\\$100.36$"},{"key":"D","text":"$\\$99.06$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, the 15% reduction gives $130 \\times 0.85 = \\$110.50$. Then, the 8% coupon applied to the sale price gives $110.50 \\times 0.92 = \\$101.66$. The value $\\$100.10$ results from applying a single combined 23% discount ($130 \\times 0.77$), which incorrectly treats the two discounts as additive. The value $\\$100.36$ comes from an arithmetic error in one of the multiplication steps. The value $\\$99.06$ comes from applying the 8% coupon to the original price first and then the 15% discount, reversing the order and miscalculating.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y6BXEU', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The equation $a(2x + 7) + 5x = 11x + b$ has infinitely many solutions for $x$, where $a$ and $b$ are constants. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$21$"},{"key":"D","text":"$-21$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding the left side gives $(2a + 5)x + 7a = 11x + b$. For the equation to have infinitely many solutions, the coefficients of $x$ and the constant terms must be equal on both sides. Setting $2a + 5 = 11$ gives $a = 3$. Then $b = 7a = 7(3) = 21$. The value 3 results from finding $a$ correctly but reporting it as $b$, a partial reasoning error. The value 7 results from misreading the question and reporting the coefficient of $a$ in the constant term rather than evaluating $7a$. The value $-21$ results from a sign error when computing $7a$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z0JW3K', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A swimming pool is being drained at a constant rate. At $t = 0$ minutes, the pool contains 4,700 gallons of water. After 15 minutes, the pool contains 3,425 gallons. Which function $w$ models the amount of water, in gallons, remaining in the pool after $t$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$w(t) = 3{,}425 - 85t$"},{"key":"B","text":"$w(t) = 4{,}700 - 85t$"},{"key":"C","text":"$w(t) = 4{,}700 - \\frac{t}{85}$"},{"key":"D","text":"$w(t) = 4{,}700 + 85t$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change is $\\frac{3{,}425 - 4{,}700}{15} = \\frac{-1{,}275}{15} = -85$ gallons per minute. Starting at 4,700 gallons, the function is $w(t) = 4{,}700 - 85t$. The function $w(t) = 3{,}425 - 85t$ incorrectly uses the 15-minute reading as the initial value instead of the value at $t = 0$. The function $w(t) = 4{,}700 - \\frac{t}{85}$ inverts the rate, confusing gallons per minute with minutes per gallon. The function $w(t) = 4{,}700 + 85t$ applies a positive rate, which would model filling rather than draining.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZV87S8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $5(2x - 3) + 4(x + 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$14x + 13$"},{"key":"B","text":"$6x + 13$"},{"key":"C","text":"$14x + 43$"},{"key":"D","text":"$14x - 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute: $5(2x-3) = 10x - 15$ and $4(x+7) = 4x + 28$. Add: $10x + 4x = 14x$ and $-15 + 28 = 13$. The result is $14x + 13$. The expression $6x + 13$ incorrectly subtracts the $x$-terms ($10x - 4x$) instead of adding them. The expression $14x + 43$ incorrectly computes $15 + 28$ instead of $-15 + 28$, a sign error on the first constant. The expression $14x - 13$ reverses the sign of the combined constant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZVA6QK', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $g$ satisfies $g(3) = 19$ and $g(11) = 51$. What is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The slope is $\\frac{51 - 19}{11 - 3} = \\frac{32}{8} = 4$. Using point-slope form: $g(x) = 4(x - 3) + 19 = 4x - 12 + 19 = 4x + 7$. Therefore $g(0) = 4(0) + 7 = 7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20L4Y1B', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Neuroscientists at the University of Geneva hypothesized in 2023 that the human brain processes musical rhythm and spoken language syntax through overlapping neural circuits. They proposed that individuals with stronger rhythmic perception abilities would also demonstrate faster processing of complex grammatical structures in their native language, because both tasks rely on the brain''s capacity to detect and predict hierarchical temporal patterns.', $lyceon_json$[{"key":"A","text":"A study finds that professional drummers score significantly higher than non-musicians on tests measuring the speed of parsing sentences with embedded subordinate clauses."},{"key":"B","text":"A study finds that listening to background music while reading has no measurable effect on reading comprehension scores among college students."},{"key":"C","text":"A study finds that children who begin structured language instruction before age five acquire substantially larger vocabularies and stronger grammatical skills than children who begin instruction later."},{"key":"D","text":"A study finds that adults who speak three or more languages perform better on visual pattern recognition tasks than monolingual adults do."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis proposes that stronger rhythmic ability correlates with faster processing of complex grammar. Finding that professional drummers, who have strong rhythmic skills, also parse complex sentences faster would directly support this proposed link. The finding about background music and reading comprehension is wrong because it concerns the effect of passive listening on comprehension, not the relationship between rhythmic ability and grammatical processing speed. The finding about early language instruction and vocabulary size is wrong because it addresses vocabulary acquisition timing, not the connection between rhythm and syntax processing. The finding about multilingual adults and visual pattern recognition is wrong because it concerns visual patterns and multilingualism, neither of which relates to the proposed rhythm-syntax connection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20LHZO7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a researcher, if added to the text, would most effectively illustrate the challenge described in the passage?', E'Conservation biologists working to reintroduce the Iberian lynx into regions of southern Portugal have encountered an unexpected obstacle. While the lynx population has grown from 94 individuals in 2002 to over 1,700 by 2023, the species'' recovery has been complicated by a concurrent decline in European rabbit populations caused by rabbit hemorrhagic disease. Because the Iberian lynx depends on rabbits for roughly 85 percent of its diet, areas that appear to have suitable habitat based on vegetation and terrain analysis may nonetheless fail to sustain lynx populations if local rabbit densities remain below critical thresholds.', $lyceon_json$[{"key":"A","text":"\"We can restore every hectare of Mediterranean scrubland the lynx needs, but if the rabbits are not there in sufficient numbers, we are essentially building an empty house.\""},{"key":"B","text":"\"The genetic diversity within the current lynx population is remarkably high considering the bottleneck the species experienced in the early 2000s.\""},{"key":"C","text":"\"Our tracking data show that reintroduced lynx typically establish territories within three months of release into new habitat areas.\""},{"key":"D","text":"\"The Iberian lynx recovery program has become a model for large carnivore reintroduction projects across the European continent.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the challenge that suitable-looking habitat may fail to support lynx if rabbit densities are too low. The quotation about building an empty house directly illustrates this problem by metaphorically capturing how restored habitat without adequate prey is insufficient. The quotation about genetic diversity addresses population genetics, which is unrelated to the prey-availability challenge described. The quotation about territory establishment discusses lynx behavioral adaptation after release, not the prey shortage obstacle. The quotation about the program being a model for other projects concerns the program''s reputation, not the specific challenge of insufficient rabbit populations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20PNLXH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The volcanologist Atsuko Nishimura—who had previously dismissed the hypothesis that subglacial eruptions could trigger rapid glacial ______ revised her position after analyzing geochemical evidence from cores extracted beneath the Vatnajökull ice cap in 2019.', $lyceon_json$[{"key":"A","text":"retreat, revised"},{"key":"B","text":"retreat—revised"},{"key":"C","text":"retreat; revised"},{"key":"D","text":"retreat. Revised"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is the option closing with an em dash before "revised" because the parenthetical clause "who had previously dismissed the hypothesis that subglacial eruptions could trigger rapid glacial retreat" was opened with an em dash after "Nishimura." Paired punctuation must be consistent: an em dash that opens a parenthetical must be closed with a matching em dash before the main clause resumes. The choice using a comma before "revised" mixes punctuation types, opening the parenthetical with an em dash but closing it with a comma, which violates the convention of matched pairs. The choice using a semicolon before "revised" is incorrect because a semicolon requires independent clauses on both sides; the material before the semicolon ends with a dependent clause embedded within an em-dash parenthetical and lacks a standalone main verb. The choice using a period before "Revised" creates the fragment "Revised her position after analyzing geochemical evidence," which has no subject and cannot stand as a sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW227QROG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration team''s responsibilities included cataloging each artifact according to its provenance, ______ the structural integrity of fragile ceramic pieces, and submitting detailed condition reports to the museum''s conservation board before any item could be displayed.', $lyceon_json$[{"key":"A","text":"to assess"},{"key":"B","text":"they assessed"},{"key":"C","text":"assessing"},{"key":"D","text":"an assessment of"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "assessing" because the sentence lists three responsibilities joined by commas and the conjunction "and," each of which must be in parallel grammatical form. The first item, "cataloging," and the third item, "submitting," are both gerunds (present participles functioning as nouns), so the second item must also be a gerund to maintain parallel structure. The choice "to assess" introduces an infinitive, which breaks the gerund pattern established by "cataloging" and "submitting." The choice "they assessed" introduces a new subject and a finite verb, creating a clause where a gerund phrase is required and disrupting the parallel list structure. The choice "an assessment of" substitutes a noun phrase for the gerund, breaking parallel structure; while semantically similar, it is grammatically inconsistent with the gerund forms of the other two list items.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
