INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25WGRR1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Lena Forsberg''s excavation of a Viking-age trading post in Birka, Sweden, uncovered over 400 fragments of silk fabric dated to the ninth century CE. Because the nearest silk-producing regions were thousands of kilometers away in Central Asia and the Byzantine Empire, Forsberg initially hypothesized that the silk arrived via long-distance trade networks. ______ isotopic analysis of the silk fibers revealed protein signatures consistent with silkworm species native to the eastern Mediterranean, narrowing the likely origin to Byzantine workshops rather than Central Asian producers.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"More precisely,"},{"key":"C","text":"For example,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'B', NULL, E'Forsberg hypothesized that silk arrived via long-distance trade from Central Asia or the Byzantine Empire. The isotopic analysis then refined that broad hypothesis by identifying the eastern Mediterranean as the specific origin, narrowing the source to Byzantine workshops. "More precisely" correctly signals that the second finding sharpens the initial claim rather than replacing or contradicting it. "In contrast" would indicate the analysis contradicted the trade-network hypothesis, but the finding actually supports and refines it by specifying which trade network. "For example" would indicate the isotopic analysis is one instance illustrating the trade-network hypothesis, but it is a refinement of the hypothesis rather than a supporting example. "In addition" would signal supplementary information on a parallel topic, but the analysis directly narrows the preceding hypothesis rather than adding an unrelated finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26PH6VU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present the tension between the potential benefits and the ethical concerns surrounding de-extinction of the woolly mammoth. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27Z5UCP', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Neuropsychologist Ravi Mehrotra''s 2022 study found that bilingual adults who regularly switch between languages exhibit significantly greater gray matter density in the dorsolateral prefrontal cortex than monolingual adults matched for age, education, and socioeconomic background. Mehrotra proposed that the sustained cognitive demands of managing two active language systems stimulate neural growth in regions governing executive function. ______ a longitudinal replication by Clara Sundqvist, tracking 1,200 participants over nine years, found that the gray matter differences were already present in childhood, before habitual code-switching had begun, suggesting that preexisting neurological variation may predispose certain individuals toward successful bilingualism rather than bilingualism itself reshaping the brain.', $lyceon_json$[{"key":"A","text":"By extension,"},{"key":"B","text":"That is, to clarify the preceding claim,"},{"key":"C","text":"Subsequently, however,"},{"key":"D","text":"To illustrate,"}]$lyceon_json$::jsonb, 'C', NULL, E'Mehrotra proposed that bilingualism causes increased gray matter density through sustained cognitive demands. Sundqvist''s later longitudinal study found the differences existed before code-switching began, suggesting preexisting neurological variation rather than bilingualism-driven brain change. The relationship involves both temporal sequence (a later study) and a challenge to the causal direction. "Subsequently, however" captures both elements: the study came afterward in time and its findings complicate Mehrotra''s causal claim. "By extension" would indicate Sundqvist''s findings logically expand Mehrotra''s conclusion, but they undermine rather than extend his causal direction. "That is" signals a restatement or clarification, but Sundqvist''s study introduces a competing interpretation rather than restating Mehrotra''s proposal. "To illustrate" signals a specific example supporting the preceding claim, but Sundqvist''s longitudinal data challenges Mehrotra''s causation argument rather than exemplifying it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29Z8KU5', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about the glassmakers of Murano?', E'In 1291, the Venetian Republic ordered all glassmakers to relocate their furnaces from Venice proper to the island of Murano. The stated justification was fire prevention, as glass furnaces posed a hazard to the densely built wooden structures of Venice. However, historians have noted that the decree also conveniently concentrated the glassmakers in a location where their movements could be monitored. Glassmakers who attempted to leave Murano without authorization faced severe penalties, including imprisonment, and in some recorded cases, the Republic dispatched agents to track down artisans who had fled to rival cities.', $lyceon_json$[{"key":"A","text":"They possessed knowledge that Venetian authorities considered valuable enough to restrict through legal and punitive measures."},{"key":"B","text":"They were primarily farmers who practiced glassmaking only as a secondary occupation during winter months."},{"key":"C","text":"They voluntarily chose to move to Murano because the island offered better raw materials for glass production."},{"key":"D","text":"They were largely indifferent to the relocation decree because Murano provided superior living conditions and resources compared to mainland Venice."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes severe penalties for unauthorized departure and agents sent to retrieve fleeing artisans, which implies the Republic valued the glassmakers'' expertise highly enough to impose strict controls. The option about being primarily farmers is wrong because the passage identifies them solely as glassmakers and provides no evidence of farming. The option about voluntarily choosing to move is wrong because the passage describes the relocation as an order from the Republic, not a voluntary choice. The option about indifference to the decree is wrong because the mention of glassmakers who fled to rival cities indicates resistance, not indifference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AILWJ9', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to highlight the economic benefit of cultivating saffron in the Taliouine region. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AYVKKI', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'During the late nineteenth century, veterinary researchers struggled to identify the cause of a devastating cattle disease that swept through sub-Saharan Africa. <u>In 1897, Arnold Theiler inoculated healthy cattle with blood serum from infected animals and observed that the recipients developed identical symptoms within eleven days.</u> This demonstration of direct transmission through blood established that the disease was caused by a pathogen rather than by environmental conditions such as tainted water or poor grazing land, as many ranchers had assumed.', $lyceon_json$[{"key":"A","text":"It describes an experiment whose results provided evidence for the conclusion presented in the following sentence."},{"key":"B","text":"It introduces a rival hypothesis that the passage ultimately rejects in favor of an environmental explanation."},{"key":"C","text":"It summarizes the overall argument of the passage in a single representative example of veterinary fieldwork."},{"key":"D","text":"It qualifies an earlier claim by noting that the researcher's methodology had significant limitations that later scientists addressed."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes Theiler''s inoculation experiment and its outcome, and the next sentence draws a conclusion from that experiment (the disease was caused by a pathogen, not environmental factors). Thus the underlined sentence provides experimental evidence for the conclusion that follows. The option about introducing a rival hypothesis is wrong because Theiler''s experiment supports the pathogen explanation rather than opposing it, and the passage rejects the environmental explanation, not the pathogen one. The option about summarizing the overall argument is wrong because the underlined sentence presents one specific experiment rather than condensing the entire passage. The option about qualifying an earlier claim with methodological limitations is wrong because the passage does not discuss any limitations of Theiler''s methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CDT425', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how does the position in Text 2 complicate the interpretation of the results described in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D7HIP0', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between tidal flat sediment patterns and storm frequency?', E'Geologist Clara Whitford and her team analyzed sediment cores extracted from tidal flats along the northern coast of the Wadden Sea. Each core preserved alternating layers of fine-grained clay and coarser sand deposits. Whitford observed that the sand layers, which are typically deposited during high-energy storm events, occurred with increasing frequency in core sections corresponding to the period between 1450 and 1650 CE. During this same interval, historical records from coastal Dutch and German communities document a marked rise in catastrophic flooding episodes. In core sections dating after 1650, the sand layers thin and become more widely spaced, a pattern Whitford attributes to a shift in North Atlantic storm tracks documented in paleoclimate reconstructions.', $lyceon_json$[{"key":"A","text":"When storm frequency in the region decreased after 1650, the sediment record reflected this change through thinner and less frequent sand layers."},{"key":"B","text":"The clay layers in the sediment cores were deposited exclusively during periods when no storms affected the Wadden Sea coast."},{"key":"C","text":"Whitford's sediment analysis contradicts the historical records of flooding in Dutch and German communities during the 1450-1650 period."},{"key":"D","text":"Sand deposits in tidal flat sediment cores are unrelated to storm activity and instead reflect seasonal tidal variation patterns in the Wadden Sea region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that after 1650 sand layers became thinner and more widely spaced, and Whitford attributes this to a shift in storm tracks, implying reduced storm activity produced less frequent and thinner sand deposits. The option about clay layers being deposited exclusively during stormless periods is wrong because the passage does not claim storms were entirely absent during clay deposition, only that clay is fine-grained and associated with lower-energy conditions. The option about the sediment analysis contradicting historical records is wrong because the passage presents the sediment data and historical records as corroborating each other. The option about sand deposits being unrelated to storms is wrong because the passage explicitly links coarser sand layers to high-energy storm events.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DJ3MB1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to explain how the structural properties of aerogel contribute to its effectiveness as an insulator. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JGPQ6R', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In the early 1900s, entomologist William Morton Wheeler observed that colonies of leafcutter ants maintain elaborate underground fungus gardens. Rather than consuming the leaves directly, the ants chew the foliage into a pulp and use it as a substrate to ______ a specific species of fungus that serves as their primary food source.', $lyceon_json$[{"key":"A","text":"cultivate"},{"key":"B","text":"suppress"},{"key":"C","text":"digest"},{"key":"D","text":"transport to neighboring colonies for redistribution among"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes ants maintaining fungus gardens and using chewed foliage as a substrate for the fungus that feeds them, indicating a deliberate growing process. "Cultivate" means to grow or tend, which precisely matches this agricultural behavior. "Suppress" means to restrain or prevent, which is the opposite of what the ants do with the fungus they depend on for food. "Digest" is wrong because the passage specifies the ants do not consume the leaves directly; instead, they process the leaves to grow fungus, not to break down the fungus itself. "Transport to neighboring colonies for redistribution among" is wrong because the passage describes what the ants do with the pulp within their own gardens, not movement between separate colonies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JIRSFK', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Philosopher Kwame Anthony Appiah has argued that the concept of a monolithic "Western civilization" is largely a modern invention rather than a coherent historical tradition. In his view, thinkers who invoke this concept to defend a fixed cultural canon tend to ______ the extensive intellectual exchanges between European, African, and Asian societies that shaped the very texts they claim as exclusively Western achievements.', $lyceon_json$[{"key":"A","text":"obscure"},{"key":"B","text":"publicize"},{"key":"C","text":"authenticate"},{"key":"D","text":"restore through institutional reform and scholarly collaboration"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage argues that defenders of a fixed Western canon overlook cross-cultural intellectual exchanges, treating certain texts as exclusively Western when they were shaped by multiple civilizations. "Obscure" means to make unclear or conceal, which fits the idea that these thinkers hide the multicultural origins of the texts. "Publicize" means to make widely known, which is the opposite of what the passage describes: these thinkers are ignoring cross-cultural exchanges, not drawing attention to them. "Authenticate" means to verify as genuine, which does not relate to the described act of ignoring intellectual exchanges between civilizations. "Restore through institutional reform and scholarly collaboration" is wrong because the passage describes these thinkers as defending a fixed canon, not as engaging in reform efforts regarding intercultural scholarship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K0I61P', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation proposed in the text?', E'Archaeologist Tomoko Ishikawa has proposed that the sudden abandonment of several large settlements along the upper Mekong River around 900 CE was driven primarily by a prolonged drought that disrupted rice cultivation. Ishikawa points to paleoclimate proxies from lake sediment cores showing a multi-decadal dry period beginning around 880 CE, and argues that communities dependent on irrigated rice paddies would have been unable to sustain populations above a few hundred individuals once annual rainfall dropped below the threshold needed to maintain canal-fed irrigation systems. Under this explanation, the residents dispersed into smaller, more mobile groups that relied on foraging and upland dry-rice cultivation in surrounding highlands.', $lyceon_json$[{"key":"A","text":"Excavations at the abandoned settlements reveal that irrigation canal systems were extensively expanded and reinforced during the period between 870 and 910 CE, with no evidence of reduced water flow in the canals during that interval."},{"key":"B","text":"Pollen analysis from a separate region of Southeast Asia indicates that lowland rice cultivation was widespread across the Mekong basin by 600 CE."},{"key":"C","text":"Oral histories collected from highland communities in the region describe ancestral migrations from lowland river valleys, though the timing of these migrations is not specified."},{"key":"D","text":"Paleoclimate records from coastal areas approximately 800 kilometers south of the upper Mekong indicate stable monsoon patterns between 850 and 950 CE in those southern coastal zones."}]$lyceon_json$::jsonb, 'A', NULL, E'Ishikawa''s explanation depends on drought disrupting irrigation. Finding that canals were expanded and showed no reduced water flow during the critical period would directly contradict the claim that insufficient rainfall caused irrigation failure, thereby undermining the drought explanation. The finding about widespread rice cultivation by 600 CE addresses the geographic spread of rice farming at an earlier date but does not speak to whether drought caused the specific abandonments around 900 CE. The finding about oral histories of lowland-to-highland migration could be consistent with Ishikawa''s theory rather than undermining it, and the unspecified timing makes it inconclusive. The finding about stable monsoon patterns 800 kilometers to the south does not undermine the proposal because regional climate conditions can differ substantially over such distances, so stability in a distant coastal area does not preclude drought along the upper Mekong.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KQW3SX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kwame Asante observed that crown-of-thorns starfish populations on the Great Barrier Reef surge dramatically during periods of elevated nutrient runoff from agricultural land. ______ reducing fertilizer discharge into coastal waterways has become a central strategy in reef conservation programs.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Conversely,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Nonetheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence establishes that nutrient runoff causes starfish population surges that threaten the reef. The second sentence states that reducing fertilizer discharge has become a conservation strategy. This is a logical consequence: because runoff drives the problem, addressing runoff became the response. "Accordingly" correctly signals that the action follows logically from the observation. "Conversely" signals an opposite or reversed relationship, but reducing runoff is consistent with, not opposite to, the finding about runoff causing harm. "Specifically" signals a narrowing detail or elaboration of the same point, but the second sentence introduces a practical response rather than specifying the observation further. "Nonetheless" signals a concession or unexpected outcome, but shifting to a runoff-reduction strategy is the expected response to the finding, not a surprising one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NVHCA7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The series of murals painted by local artists on abandoned warehouses along the Guadalquivir ______ a renewed interest in public art among residents of the surrounding neighborhoods.', $lyceon_json$[{"key":"A","text":"reflects"},{"key":"B","text":"reflect"},{"key":"C","text":"reflecting"},{"key":"D","text":"have reflected"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "reflects" because the subject of the sentence is "The series," which is singular. The intervening prepositional phrases "of murals painted by local artists on abandoned warehouses along the Guadalquivir" do not change the grammatical number of the subject. A singular subject requires a singular verb form. The choice "reflect" is a plural verb form that incorrectly treats "murals" or "artists" as the subject rather than "series." The choice "reflecting" is a present participle that would leave the sentence without a finite main verb, creating a sentence fragment. The choice "have reflected" uses the plural auxiliary "have," which does not agree with the singular subject "series."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NXGIOW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the implications of the study''s findings for urban stormwater management?', E'Civil engineer Priya Nagarajan and her colleagues conducted a three-year field study comparing the water absorption rates of eleven different permeable pavement systems installed in parking lots across three mid-Atlantic cities. The study found that pavements incorporating a subsurface gravel reservoir retained between 78 and 93 percent of rainfall from storms producing up to 4.5 centimeters of precipitation. However, performance dropped sharply during storms exceeding 6 centimeters: retention rates fell to between 31 and 47 percent, with the excess flowing into conventional storm drains. Nagarajan also noted that in lots where vehicle traffic exceeded 400 passes per day, surface pore clogging reduced absorption rates by an additional 12 to 19 percent within eighteen months, a rate of degradation substantially faster than manufacturer projections had anticipated.', $lyceon_json$[{"key":"A","text":"Permeable pavement systems may be less effective as standalone stormwater solutions in areas that experience frequent heavy rainfall events combined with high vehicle traffic volumes."},{"key":"B","text":"Permeable pavement systems are likely to eliminate the need for conventional storm drains in most mid-Atlantic urban areas within the next decade."},{"key":"C","text":"The subsurface gravel reservoirs used in the study were designed primarily to filter pollutants from stormwater rather than to increase water retention capacity."},{"key":"D","text":"Manufacturer projections of pavement durability were shown to be accurate for lots with fewer than 400 vehicle passes per day, confirming that current industry testing standards reliably predict field performance."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that permeable pavements lose effectiveness during heavy storms (retention dropping to 31-47 percent) and degrade faster than expected under high traffic, so combining both conditions would further limit their reliability as standalone solutions. The option about eliminating conventional storm drains contradicts the passage, which shows excess water already flowing into conventional drains during heavy storms. The option about gravel reservoirs filtering pollutants is wrong because the passage discusses the reservoirs only in the context of water retention, not pollutant filtration. The option about manufacturer projections being confirmed for lower-traffic lots is wrong because the passage only reports that degradation exceeded projections for high-traffic lots and does not confirm projections for lower-traffic conditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O3J4DH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeological surveys of the Dholavira site have uncovered evidence of a sophisticated water management system with three key ______ an enormous reservoir carved into bedrock, a series of cascading channels for rainwater collection, and a network of underground conduits linking the city''s neighborhoods.', $lyceon_json$[{"key":"A","text":"components, an"},{"key":"B","text":"components: an"},{"key":"C","text":"components; an"},{"key":"D","text":"components an"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "components: an" because a colon is the appropriate punctuation mark after a complete independent clause that introduces a list of specifying items. The clause "Archaeological surveys of the Dholavira site have uncovered evidence of a sophisticated water management system with three key components" is a complete independent clause, and the three items that follow (an enormous reservoir, a series of channels, and a network of conduits) specify what those components are. The choice "components, an" is incorrect because a comma alone cannot properly introduce a list after a complete clause; it creates ambiguity about whether the following items are appositives or a new clause. The choice "components; an" is wrong because a semicolon must join two independent clauses, and the list of noun phrases that follows is not an independent clause. The choice "components an" omits all punctuation between the introductory clause and the list, producing a run-on that is difficult to parse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PD930T', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist Keiko Taniguchi, who has spent over fourteen years studying bioluminescent organisms in the Mariana ______ recently identified a previously unknown species of deep-sea jellyfish capable of emitting ultraviolet light.', $lyceon_json$[{"key":"A","text":"Trench, recently"},{"key":"B","text":"Trench recently"},{"key":"C","text":"Trench; recently"},{"key":"D","text":"Trench. Recently"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "Trench, recently" because the clause "who has spent over fourteen years studying bioluminescent organisms in the Mariana Trench" is a nonrestrictive relative clause set off by commas. The opening comma appears after "Taniguchi," so a closing comma must appear after "Trench" to complete the pair before the main clause resumes with "recently identified." The choice "Trench recently" omits the closing comma of the nonrestrictive clause, violating the convention that paired commas must bracket such clauses. The choice "Trench; recently" incorrectly uses a semicolon, which requires two independent clauses on either side; the segment before the semicolon ends with a dependent clause and has no main verb, so it cannot stand alone. The choice "Trench. Recently" places a period after a dependent-clause fragment, since "The marine biologist Keiko Taniguchi, who has spent over fourteen years studying bioluminescent organisms in the Mariana Trench" has no main verb and is not a complete sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q38HRX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'When the 1927 Mississippi River flood displaced hundreds of thousands of residents across seven states, local governments quickly discovered that their existing relief infrastructure was ______. Makeshift shelters ran out of supplies within days, and volunteer organizations struggled to coordinate their efforts across such a vast affected area.', $lyceon_json$[{"key":"A","text":"inadequate"},{"key":"B","text":"profitable"},{"key":"C","text":"intentional"},{"key":"D","text":"lacking in public awareness or visibility"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes shelters running out of supplies and organizations struggling to coordinate, indicating that the existing relief infrastructure was not sufficient for the crisis. "Inadequate" means not enough or not good enough for a particular purpose, which fits precisely. "Profitable" is wrong because the passage discusses whether the infrastructure could handle the disaster, not whether it generated revenue. "Intentional" is wrong because the passage addresses the capacity of the infrastructure, not whether it was deliberately created. "Lacking in public awareness or visibility" is wrong because the passage focuses on the infrastructure''s practical shortcomings in handling the flood, not on whether the public knew about it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QL8CFR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the research team initially hypothesized that the compound''s unusual fluorescence ______ by ambient temperature alone, subsequent trials revealed that atmospheric pressure exerted an equally measurable influence.', $lyceon_json$[{"key":"A","text":"were caused"},{"key":"B","text":"was caused"},{"key":"C","text":"has been caused"},{"key":"D","text":"are being caused"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "was caused" because the subject of the subordinate clause is "fluorescence," which is singular, requiring a singular verb. Additionally, the main clause verb "hypothesized" and the later verb "revealed" both use the simple past tense, so the verb in the subordinate clause must also be in the past tense to maintain consistency. The choice "were caused" uses the correct past tense and passive voice but the incorrect plural number, failing to agree with the singular subject "fluorescence." The choice "has been caused" uses the present perfect tense, which is inconsistent with the past-tense framing established by "initially hypothesized" and "subsequent trials revealed." The choice "are being caused" combines the present tense with the plural number, conflicting with both the singular subject and the past-tense narrative context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RHCS80', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, what is the relationship between the findings described in Text 1 and the argument presented in Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S4ZIDB', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2021, a team of ornithologists at the University of Lund published findings on the Arctic tern''s annual migration. Using miniaturized geolocators attached to 47 birds, the researchers tracked routes spanning approximately 71,000 kilometers per year. Remarkably, the terns did not follow direct paths between their breeding grounds in Greenland and their wintering areas in Antarctica. Instead, they exploited prevailing wind patterns in the Atlantic, taking sweeping S-shaped detours that, while longer in distance, required significantly less energy than a straight-line route would have demanded.', $lyceon_json$[{"key":"A","text":"Arctic terns migrate farther each year than any other bird species studied to date."},{"key":"B","text":"Researchers discovered that Arctic terns follow indirect migration routes that conserve energy by taking advantage of wind patterns."},{"key":"C","text":"The geolocators used in the Lund study represented a technological breakthrough in ornithological tracking methods."},{"key":"D","text":"Arctic terns breed exclusively in Greenland before traveling to Antarctica for the winter season."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage focuses on the finding that Arctic terns take indirect, wind-assisted routes that save energy rather than flying directly. The option about terns migrating farther than any other species is wrong because the passage never compares tern migration distances to those of other species. The option about geolocators being a technological breakthrough is wrong because the passage mentions geolocators only as the tool used, not as the subject of the findings. The option about terns breeding exclusively in Greenland is wrong because the passage mentions Greenland as one breeding ground but does not claim it is the only one, and this detail is not the main idea.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TMCBIQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2022 paper published in Nature Ecology & Evolution, ecologist Suzanne Simard and colleagues presented evidence that mycorrhizal fungal networks connecting the roots of trees in temperate forests do not distribute resources equitably. Using isotopic carbon tracers injected into mature Douglas fir trees, the team demonstrated that carbon flowed preferentially toward genetically related seedlings rather than toward unrelated neighbors, even when unrelated neighbors were in greater physiological distress. This finding complicates the widely circulated narrative of the "wood wide web" as an egalitarian communal system. Simard herself has cautioned against interpreting the networks through an anthropomorphic lens of cooperation, noting that kin-biased resource allocation more closely resembles the selective investment patterns documented in animal family groups than it does any model of generalized reciprocity among unrelated organisms.', $lyceon_json$[{"key":"A","text":"Simard's research shows that fungal networks in forests allocate resources preferentially to genetically related trees, undermining the portrayal of these networks as egalitarian communal systems."},{"key":"B","text":"The \"wood wide web\" functions as an egalitarian system that distributes carbon equally among all connected trees regardless of genetic relatedness."},{"key":"C","text":"Simard's isotopic tracer methodology was innovative primarily because it allowed researchers to measure photosynthesis rates in mature Douglas fir trees for the first time."},{"key":"D","text":"Mycorrhizal fungal networks have been shown to prioritize the survival of physiologically distressed trees regardless of genetic relatedness, confirming earlier models of generalized reciprocity in complex forest ecosystems."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Simard''s team found that fungal networks channel resources preferentially toward kin, which challenges the egalitarian narrative of the wood wide web. The option claiming the wood wide web is egalitarian directly contradicts the passage''s central finding. The option about the tracer methodology measuring photosynthesis rates is wrong because the passage describes the tracers as tracking carbon flow between trees, not measuring photosynthesis rates, and the passage does not claim the methodology itself is the main subject. The option about networks prioritizing distressed trees contradicts the passage, which states carbon flowed to related seedlings even when unrelated neighbors were in greater distress.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WULTSQ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Behavioral economist Sendhil Mullainathan has studied how financial scarcity affects cognitive performance. His research suggests that people experiencing poverty devote substantial mental resources to immediate financial pressures, leaving fewer cognitive resources available for long-term planning. <u>In one experiment, shoppers at a New Jersey mall were asked to consider how they would handle an unexpected car repair costing either one hundred fifty or fifteen hundred dollars; lower-income participants performed significantly worse on subsequent cognitive tests, but only when the hypothetical repair was expensive.</u> Mullainathan interprets such findings as evidence that scarcity itself imposes a "bandwidth tax" on the mind, a tax that has nothing to do with inherent ability and everything to do with the demands of managing with too little.', $lyceon_json$[{"key":"A","text":"It provides experimental evidence that illustrates and supports the cognitive mechanism described in the surrounding sentences."},{"key":"B","text":"It introduces a methodological objection to the broader research program that the passage otherwise endorses."},{"key":"C","text":"It offers a biographical detail about the researcher that explains his professional interest in the relationship between poverty and cognition."},{"key":"D","text":"It presents an anomalous result that complicates the theoretical framework the passage attributes to the researcher and that later studies have not been able to replicate satisfactorily."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes a specific experiment in which lower-income participants showed reduced cognitive performance when confronted with an expensive hypothetical expense. This directly illustrates the preceding claim that financial scarcity diverts mental resources, and the following sentence interprets such findings as evidence for the bandwidth tax concept. The option about a methodological objection is wrong because the experiment supports rather than challenges Mullainathan''s research program. The option about biographical detail is wrong because the sentence describes an experiment at a mall, not personal information about the researcher. The option about an anomalous or unreplicable result is wrong because the passage presents the finding as consistent with and supportive of Mullainathan''s framework, not as a complication of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y66D9V', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'Historian Melissa Borja has argued that the wave of Southeast Asian refugees who arrived in the United States during the late 1970s and 1980s reshaped American religious geography in ways that scholars have only recently begun to document. While many of these refugees practiced Buddhism, Catholicism, or animist traditions before emigrating, their religious lives in the United States were far from static reproductions of homeland practices. Borja''s research on Hmong communities in Minnesota shows that refugee families often synthesized elements from multiple traditions, creating hybrid spiritual practices that responded to the pressures of resettlement, economic uncertainty, and generational change. These adaptive practices, Borja contends, challenge the common scholarly assumption that immigrant religion is primarily a vehicle for cultural preservation.', $lyceon_json$[{"key":"A","text":"Southeast Asian refugees who settled in the United States developed hybrid religious practices that complicate the assumption that immigrant religion merely preserves homeland traditions."},{"key":"B","text":"Melissa Borja's research demonstrates that Hmong communities in Minnesota abandoned their traditional animist beliefs after resettling in the United States."},{"key":"C","text":"The religious practices of Southeast Asian refugees have been thoroughly documented by American scholars since the 1980s."},{"key":"D","text":"Economic hardship was the primary factor that caused Southeast Asian refugees to abandon their original religious traditions after arriving in the United States."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Borja''s argument that Southeast Asian refugees created hybrid spiritual practices that challenge the scholarly view of immigrant religion as cultural preservation. The option about Hmong communities abandoning animist beliefs is wrong because the passage describes synthesis of multiple traditions, not abandonment of any. The option about thorough documentation since the 1980s is wrong because the passage explicitly states that scholars have only recently begun to document these changes. The option about economic hardship being the primary factor is wrong because the passage lists economic uncertainty as one of several pressures and describes adaptive synthesis rather than abandonment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZC885D', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Musicologist Kofi Agawu has observed that Western listeners often describe West African drumming as "polyrhythmic," emphasizing the simultaneous layering of independent rhythmic patterns. Agawu argues, however, that this description imposes a Western analytical framework onto music that its practitioners understand differently. For Dagomba drummers in northern Ghana, the seemingly independent patterns are organized around a single recurring timeline, a short rhythmic figure that every performer uses as a shared reference point. Each drummer''s part interlocks with this timeline rather than operating independently of it. By foregrounding the timeline as the organizing principle, Agawu contends, scholars can move beyond the polyrhythmic label and develop a more accurate account of how the music actually functions within its own tradition.', $lyceon_json$[{"key":"A","text":"It introduces a common characterization of a musical tradition, argues that the characterization reflects a misapplied framework, and proposes an alternative analytical approach."},{"key":"B","text":"It traces the historical evolution of a musical form from its origins in one region to its adaptation and reinterpretation in another."},{"key":"C","text":"It presents two equally valid methods for analyzing a musical tradition and concludes that scholars should employ both methods in combination."},{"key":"D","text":"It describes a technical musical concept, identifies the researcher who first documented it, and then catalogs the variations of that concept across several West African cultures."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage begins with the common Western characterization of West African drumming as polyrhythmic, then argues that this characterization imposes a Western framework, and finally proposes the timeline-based approach as a more accurate alternative. The option about tracing historical evolution is wrong because the passage does not discuss how the music changed over time or moved between regions. The option about two equally valid methods is wrong because Agawu explicitly argues the polyrhythmic framework is inaccurate; the passage does not present it as equally valid. The option about cataloging variations across cultures is wrong because the passage focuses on Dagomba drumming to illustrate Agawu''s point and does not survey multiple cultures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
